    template <typename T> void conjugate(const hoNDArray<T>& x, hoNDArray<T>& r) {
        if (r.get_number_of_elements() != x.get_number_of_elements()) {
            r.create(x.dimensions());
        }
        Gadgetron::transform(x,r,[](auto val){return conj(val);});
    }

