    template <typename T> void addEpsilon(hoNDArray<T>& x) {
        constexpr auto eps = std::numeric_limits<realType_t<T>>::epsilon();
        using std::abs;
        transform(x,x,[&](auto val){return (abs(val) < eps ) ? val+eps : val; });
    }

